  1038	/** Calculate area after rotation, area coordinate is relative to original topleft pixel(and pivot too)
  1039	 *  i.e. if angle=0, output is x0=0, y0=0, x1=w-1, y1=h-1
  1040	 *
  1041	 * @param[out] output
  1042	 * @param[in] w width
  1043	 * @param[in] h height
  1044	 * @param[in] angle angle in 0.1 degree
  1045	 * @param[in] pivot pivot
  1046	 * @return sinus of 'angle'. sin(-90) = -32767, sin(90) = 32767
  1047	 */
  1048	void EPIC_GetRotatedArea(EPIC_AreaTypeDef *output, uint16_t w, uint16_t h, int16_t angle,
  1049	                         const EPIC_PointTypeDef *pivot)
  1050	{
  1051	    int32_t angle_low = angle / 10;
  1052	    int32_t angle_hight = angle_low + 1;
  1053	    int32_t angle_rem = angle  - (angle_low * 10);
  1054	
  1055	    int32_t s1 = EPIC_TrigoSin(angle_low);
  1056	    int32_t s2 = EPIC_TrigoSin(angle_hight);
  1057	
  1058	    int32_t c1 = EPIC_TrigoSin(angle_low + 90);
  1059	    int32_t c2 = EPIC_TrigoSin(angle_hight + 90);
  1060	
  1061	    int32_t sinma = (s1 * (10 - angle_rem) + s2 * angle_rem) / 10;
  1062	    int32_t cosma = (c1 * (10 - angle_rem) + c2 * angle_rem) / 10;
  1063	
  1064	    EPIC_PointTypeDef lt;
  1065	    EPIC_PointTypeDef rt;
  1066	    EPIC_PointTypeDef lb;
  1067	    EPIC_PointTypeDef rb;
  1068	
  1069	    int16_t xt;
  1070	    int16_t yt;
  1071	
  1072	    EPIC_AreaTypeDef a;
  1073	    a.x0 = (-pivot->x);
  1074	    a.y0 = (-pivot->y);
  1075	    a.x1 = (w - pivot->x);
  1076	    a.y1 = (h - pivot->y);
  1077	
  1078	    xt = a.x0;
  1079	    yt = a.y0;
  1080	    lt.x = ((cosma * xt - sinma * yt) >> EPIC_TRIGO_SHIFT) + pivot->x;
  1081	    lt.y = ((sinma * xt + cosma * yt) >> EPIC_TRIGO_SHIFT) + pivot->y;
  1082	
  1083	    xt = a.x1;
  1084	    yt = a.y0;
  1085	    rt.x = ((cosma * xt - sinma * yt) >> EPIC_TRIGO_SHIFT) + pivot->x;
  1086	    rt.y = ((sinma * xt + cosma * yt) >> EPIC_TRIGO_SHIFT) + pivot->y;
  1087	
  1088	    xt = a.x0;
  1089	    yt = a.y1;
  1090	    lb.x = ((cosma * xt - sinma * yt) >> EPIC_TRIGO_SHIFT) + pivot->x;
  1091	    lb.y = ((sinma * xt + cosma * yt) >> EPIC_TRIGO_SHIFT) + pivot->y;
  1092	
  1093	    xt = a.x1;
  1094	    yt = a.y1;
  1095	    rb.x = ((cosma * xt - sinma * yt) >> EPIC_TRIGO_SHIFT) + pivot->x;
  1096	    rb.y = ((sinma * xt + cosma * yt) >> EPIC_TRIGO_SHIFT) + pivot->y;
  1097	
  1098	    output->x0 = EPIC_MATH_MIN4(lb.x, lt.x, rb.x, rt.x) - 1;
  1099	    output->x1 = EPIC_MATH_MAX4(lb.x, lt.x, rb.x, rt.x) + 1;
  1100	    output->y0 = EPIC_MATH_MIN4(lb.y, lt.y, rb.y, rt.y) - 1;
  1101	    output->y1 = EPIC_MATH_MAX4(lb.y, lt.y, rb.y, rt.y) + 1;
  1102	}
